//! Asset manifest (`engine/assets/manifest.toml`) types.
//!
//! The manifest is generated by `gen-manifest` from `engine/assets/sources.toml`
//! and is the only thing `fetch-assets` and [`crate::AssetStore`] read at
//! runtime. Every downloadable file is listed with its exact URL, byte size and
//! (when the source publishes one) MD5, per resolution.

use std::fmt;
use std::path::Path;
use std::str::FromStr;

use serde::{Deserialize, Serialize};

use crate::AssetError;

/// Current manifest schema version.
pub const MANIFEST_SCHEMA: u32 = 1;

/// Texture/HDRI resolution tier as published by the source sites.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub enum Res {
    #[serde(rename = "1k")]
    R1k,
    #[serde(rename = "2k")]
    R2k,
    #[serde(rename = "4k")]
    R4k,
    #[serde(rename = "8k")]
    R8k,
}

impl Res {
    /// All tiers, smallest first.
    pub const ALL: [Res; 4] = [Res::R1k, Res::R2k, Res::R4k, Res::R8k];

    /// Short name (`"2k"`), also used as the cache sub-directory.
    pub fn as_str(self) -> &'static str {
        match self {
            Res::R1k => "1k",
            Res::R2k => "2k",
            Res::R4k => "4k",
            Res::R8k => "8k",
        }
    }

    /// Nominal pixel width (textures are square, HDRIs are 2:1 with this width).
    pub fn pixels(self) -> u32 {
        match self {
            Res::R1k => 1024,
            Res::R2k => 2048,
            Res::R4k => 4096,
            Res::R8k => 8192,
        }
    }
}

impl fmt::Display for Res {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl FromStr for Res {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.trim().to_ascii_lowercase().as_str() {
            "1k" => Ok(Res::R1k),
            "2k" => Ok(Res::R2k),
            "4k" => Ok(Res::R4k),
            "8k" => Ok(Res::R8k),
            other => Err(format!(
                "unknown resolution '{other}' (expected 1k, 2k, 4k or 8k)"
            )),
        }
    }
}

/// What an asset is.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum AssetKind {
    /// Tiling PBR material (a set of texture maps).
    Texture,
    /// Equirectangular HDR environment map.
    Hdri,
    /// glTF 2.0 model (with its buffers and textures).
    Model,
}

impl fmt::Display for AssetKind {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            AssetKind::Texture => "texture",
            AssetKind::Hdri => "hdri",
            AssetKind::Model => "model",
        })
    }
}

/// Where an asset comes from.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Source {
    Polyhaven,
    Ambientcg,
}

impl fmt::Display for Source {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Source::Polyhaven => "Poly Haven",
            Source::Ambientcg => "ambientCG",
        })
    }
}

/// The meaning of one file (or archive member).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Role {
    /// Base colour / diffuse albedo, sRGB.
    Albedo,
    /// Tangent-space normal map; see [`FileEntry::normal`] for its convention.
    Normal,
    /// Perceptual roughness, linear, single channel.
    Roughness,
    /// Metalness, linear, single channel.
    Metalness,
    /// Ambient occlusion, linear, single channel.
    Ao,
    /// Packed R = AO, G = roughness, B = metalness (glTF ORM layout), linear.
    Arm,
    /// Displacement / height, linear, single channel (0.5 = reference plane on Poly Haven).
    Height,
    /// Emissive colour, sRGB.
    Emission,
    /// Opacity / alpha mask, linear.
    Opacity,
    /// Equirectangular HDR environment (Radiance `.hdr` or OpenEXR).
    Hdri,
    /// The `.gltf`/`.glb` entry point of a model.
    Gltf,
    /// A buffer or texture referenced by the glTF file (path relative to it).
    GltfDependency,
    /// A downloadable archive whose members are listed in [`FileEntry::members`].
    Archive,
}

impl Role {
    /// True for maps that hold colour and must be decoded as sRGB.
    pub fn is_srgb(self) -> bool {
        matches!(self, Role::Albedo | Role::Emission)
    }
}

/// Normal-map green-channel convention.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum NormalConvention {
    /// OpenGL / glTF / Blender: +Y (green) points "up" the V axis (bitangent = cross(N, T) * w).
    #[default]
    Gl,
    /// DirectX / Unreal / 3ds Max: green is inverted relative to OpenGL.
    Dx,
}

/// Archive format of a [`Role::Archive`] file.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ArchiveKind {
    Zip,
}

/// One member extracted from an archive.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ArchiveMember {
    pub role: Role,
    /// File name inside the archive.
    pub name: String,
    /// Destination path relative to the asset's cache directory.
    pub path: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub normal: Option<NormalConvention>,
}

/// One downloadable file.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct FileEntry {
    pub res: Res,
    pub role: Role,
    /// Destination path relative to the asset's cache directory (`cache/<id>/`),
    /// always forward slashes, starting with the resolution (`2k/...`).
    pub path: String,
    pub url: String,
    /// Exact size in bytes as published by the source API.
    pub size: u64,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub md5: Option<String>,
    /// Convention of a [`Role::Normal`] map.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub normal: Option<NormalConvention>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub archive: Option<ArchiveKind>,
    #[serde(default, rename = "member", skip_serializing_if = "Vec::is_empty")]
    pub members: Vec<ArchiveMember>,
}

/// One asset (material, HDRI or model).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AssetEntry {
    /// Stable identifier used by engine code, e.g. `tex.asphalt`.
    pub id: String,
    pub kind: AssetKind,
    pub source: Source,
    /// Asset slug / id on the source site.
    pub slug: String,
    pub name: String,
    /// Human-facing page on the source site.
    pub page: String,
    pub authors: Vec<String>,
    /// SPDX licence id; always `CC0-1.0` in this manifest.
    pub license: String,
    /// How the licence was verified when the manifest was generated.
    pub license_evidence: String,
    /// Optional assets are skipped by `fetch-assets` unless `--all` or `--only` selects them.
    #[serde(default)]
    pub optional: bool,
    /// Highest resolution worth downloading for this asset (caps `--res`).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub max_res: Option<Res>,
    /// Real-world size of one texture tile in metres (width, height), when published.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tile_size_m: Option<[f32; 2]>,
    /// Default metalness for materials that ship without a metalness map.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub metalness: Option<f32>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub tags: Vec<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub notes: Option<String>,
    #[serde(default, rename = "file")]
    pub files: Vec<FileEntry>,
}

impl AssetEntry {
    /// Resolutions this asset has files for, smallest first.
    pub fn resolutions(&self) -> Vec<Res> {
        let mut v: Vec<Res> = self.files.iter().map(|f| f.res).collect();
        v.sort();
        v.dedup();
        v
    }

    /// Files at one resolution.
    pub fn files_at(&self, res: Res) -> impl Iterator<Item = &FileEntry> {
        self.files.iter().filter(move |f| f.res == res)
    }

    /// Total download size at one resolution.
    pub fn download_size(&self, res: Res) -> u64 {
        self.files_at(res).map(|f| f.size).sum()
    }

    /// Choose the resolution to download/use given a wish: the wish capped by
    /// [`AssetEntry::max_res`], falling back to the nearest lower tier the
    /// asset offers, then to the smallest it offers.
    pub fn pick_res(&self, wish: Res) -> Option<Res> {
        let wish = match self.max_res {
            Some(cap) if cap < wish => cap,
            _ => wish,
        };
        let avail = self.resolutions();
        avail
            .iter()
            .rev()
            .find(|r| **r <= wish)
            .or_else(|| avail.first())
            .copied()
    }
}

/// Default resolutions per asset kind.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Defaults {
    pub texture_res: Res,
    pub hdri_res: Res,
    pub model_res: Res,
}

impl Default for Defaults {
    fn default() -> Self {
        Defaults {
            texture_res: Res::R2k,
            hdri_res: Res::R4k,
            model_res: Res::R2k,
        }
    }
}

impl Defaults {
    pub fn for_kind(&self, kind: AssetKind) -> Res {
        match kind {
            AssetKind::Texture => self.texture_res,
            AssetKind::Hdri => self.hdri_res,
            AssetKind::Model => self.model_res,
        }
    }
}

/// The whole manifest.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Manifest {
    pub schema: u32,
    /// Free-form note on how/when the manifest was generated.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub generated: Option<String>,
    #[serde(default)]
    pub defaults: Defaults,
    #[serde(default, rename = "asset")]
    pub assets: Vec<AssetEntry>,
}

impl Manifest {
    /// Parse a manifest from TOML text and validate it.
    pub fn from_toml_str(text: &str) -> Result<Self, AssetError> {
        let m: Manifest =
            toml::from_str(text).map_err(|e| AssetError::Manifest(format!("parse error: {e}")))?;
        m.validate()?;
        Ok(m)
    }

    /// Read and parse a manifest file.
    pub fn load(path: &Path) -> Result<Self, AssetError> {
        let text = std::fs::read_to_string(path).map_err(|e| AssetError::io(path, e))?;
        Self::from_toml_str(&text)
    }

    /// Serialise to TOML.
    pub fn to_toml_string(&self) -> Result<String, AssetError> {
        toml::to_string(self).map_err(|e| AssetError::Manifest(format!("serialise error: {e}")))
    }

    /// Look up an asset by id.
    pub fn get(&self, id: &str) -> Option<&AssetEntry> {
        self.assets.iter().find(|a| a.id == id)
    }

    /// Structural checks: unique ids, CC0 only, sane relative paths.
    pub fn validate(&self) -> Result<(), AssetError> {
        if self.schema != MANIFEST_SCHEMA {
            return Err(AssetError::Manifest(format!(
                "schema {} not supported (expected {MANIFEST_SCHEMA})",
                self.schema
            )));
        }
        let mut seen = std::collections::HashSet::new();
        for a in &self.assets {
            if !seen.insert(a.id.as_str()) {
                return Err(AssetError::Manifest(format!(
                    "duplicate asset id '{}'",
                    a.id
                )));
            }
            if a.license != "CC0-1.0" {
                return Err(AssetError::Manifest(format!(
                    "asset '{}' has licence '{}', only CC0-1.0 is allowed",
                    a.id, a.license
                )));
            }
            let check_path = |p: &str| -> Result<(), AssetError> {
                let bad = p.is_empty()
                    || p.starts_with('/')
                    || p.contains('\\')
                    || p.contains(':')
                    || p.split('/').any(|c| c == ".." || c.is_empty());
                if bad {
                    Err(AssetError::Manifest(format!(
                        "asset '{}': unsafe path '{p}'",
                        a.id
                    )))
                } else {
                    Ok(())
                }
            };
            for f in &a.files {
                check_path(&f.path)?;
                for m in &f.members {
                    check_path(&m.path)?;
                }
                if f.role == Role::Archive && (f.archive.is_none() || f.members.is_empty()) {
                    return Err(AssetError::Manifest(format!(
                        "asset '{}': archive file '{}' without archive kind or members",
                        a.id, f.path
                    )));
                }
            }
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn res_roundtrip_and_pick() {
        assert_eq!("2K".parse::<Res>().unwrap(), Res::R2k);
        assert!(Res::R1k < Res::R4k);
        let mut a = AssetEntry {
            id: "tex.x".into(),
            kind: AssetKind::Texture,
            source: Source::Polyhaven,
            slug: "x".into(),
            name: "X".into(),
            page: String::new(),
            authors: vec![],
            license: "CC0-1.0".into(),
            license_evidence: String::new(),
            optional: false,
            max_res: None,
            tile_size_m: None,
            metalness: None,
            tags: vec![],
            notes: None,
            files: vec![],
        };
        for r in [Res::R1k, Res::R2k] {
            a.files.push(FileEntry {
                res: r,
                role: Role::Albedo,
                path: format!("{r}/a.jpg"),
                url: String::new(),
                size: 1,
                md5: None,
                normal: None,
                archive: None,
                members: vec![],
            });
        }
        assert_eq!(a.pick_res(Res::R4k), Some(Res::R2k));
        assert_eq!(a.pick_res(Res::R1k), Some(Res::R1k));
        a.max_res = Some(Res::R1k);
        assert_eq!(a.pick_res(Res::R4k), Some(Res::R1k));
    }
}
